mapper.select:
SELECT COUNT(*) CNT
  FROM GOLF_RECEIPT_INF
 WHERE USER_ID = #{userId,jdbcType=VARCHAR}
   AND RCP_KIND = #{rcpKind,jdbcType=VARCHAR}

SELECT A.USER_ID , A.RCP_NUMBER , B.GOLF_NAME , CASE WHEN C.DEL_KIND = '2' THEN '왕복' ELSE '편도' END DEL_KIND , CASE WHEN A.SR_TYPE = 'R' THEN '회수' ELSE '발송' END SR_TYPE , CASE WHEN A.RCP_INF_STAT = '0' THEN CB_PAYSTAT_CODE(F.PAY_STAT, F.PAY_GUBUN) ELSE CB_RCPINFSTAT_CODE(A.RCP_INF_STAT) END RCP_INF_STAT , CASE WHEN C.DEL_KIND = '2' THEN (SELECT SUM(G.PD_PAY) FROM GOLF_RECEIPT_INF G WHERE G.RCP_SEQ = C.RCP_SEQ) ELSE A.PD_PAY END PD_PAY , A.PD_INDIV_PRICE , CASE WHEN C.DEL_KIND = '2' THEN CONCAT('GRP',A.RCP_SEQ) ELSE '' END ORDER_ID , A.PD_BARCODE , A.EXT_COMP , REPLACE(A.EXT_COMP_TELNUM,'-','') AS EXT_COMP_TELNUM , A.REG_DATE , IFNULL(A.CAN_REASON,'') AS CAN_REASON , A.CUS_RE_ADDR1 , IFNULL(A.CUS_RE_ADDR2,'') AS CUS_RE_ADDR2 , A.CUS_SEND_ZIP , A.CUS_RE_ZIP , A.SEND_ISL_YN , A.RECV_ISL_YN , A.CHANGE_DELTYPE_YN , A.CUS_RECEIPT_NM , REPLACE(A.CUS_RECEIPT_TELNUM,'-','') AS CUS_RECEIPT_TELNUM , DATE_FORMAT(STR_TO_DATE(C.GAME_DT,'%Y-%m-%d'), '%Y%m%d') AS GAME_DT , DATE_FORMAT(STR_TO_DATE(C.GAME_END_DT,'%Y-%m-%d'), '%Y%m%d') AS GAME_END_DT , A.PD_GOLF_CNT , A.PD_CNT , A.CUS_SEND_NM , A.CUS_SEND_ADDR1 , IFNULL(A.CUS_SEND_ADDR2,'') AS CUS_SEND_ADDR2 , REPLACE(A.CUS_SEND_TELNUM,'-','') AS CUS_SEND_TELNUM , DATE_FORMAT(STR_TO_DATE(A.PIC_REQ_DT,'%Y-%m-%d'), '%Y%m%d') AS PIC_REQ_DT , A.CUS_RE_NM , REPLACE(A.CUS_RE_TELNUM2,'-','') AS CUS_RE_TELNUM , D.GOLF_NAME AS CUS_RE_GOLF_NAME , A.PD_MEMO , A.PD_REC_DT , CASE WHEN A.SR_TYPE='S' THEN DATE_FORMAT(STR_TO_DATE(E.PIC_REQ_DT,'%Y-%m-%d'), '%Y%m%d') ELSE '' END RT_PIC_REQ_DT , CASE WHEN A.SR_TYPE='S' THEN REPLACE(E.CUS_SEND_TELNUM2,'-','') ELSE '' END RT_CUS_RE_TELNUM , CASE WHEN A.SR_TYPE='S' THEN E.CUS_SEND_NM ELSE '' END RT_CUS_RE_NM , CASE WHEN A.SR_TYPE='S' THEN E.CUS_SEND_ADDR1 ELSE '' END RT_CUS_RE_ADDR1 , CASE WHEN A.SR_TYPE='S' THEN IFNULL(E.CUS_SEND_ADDR2,'') ELSE '' END RT_CUS_RE_ADDR2 , CASE WHEN A.SR_TYPE='S' THEN E.CUS_SEND_ZIP ELSE '' END RT_CUS_RE_ZIP , A.SEND_GOLF_SEQ , A.RECV_GOLF_SEQ FROM GOLF_RECEIPT_INF A LEFT OUTER JOIN GOLF_INF B ON A.SEND_GOLF_SEQ = B.GOLF_SEQ LEFT OUTER JOIN GOLF_RECEIPT_MST C ON A.RCP_SEQ = C.RCP_SEQ LEFT OUTER JOIN GOLF_INF D ON A.RECV_GOLF_SEQ = D.GOLF_SEQ LEFT OUTER JOIN (SELECT *FROM GOLF_RECEIPT_INF E WHERE E.RCP_SEQ = E.RCP_SEQ AND E.SR_TYPE='R') E ON A.RCP_SEQ = E.RCP_SEQ LEFT OUTER JOIN GOLF_RECEIPT_PAY F ON A.RCP_INF_SEQ = F.RCP_INF_SEQ AND F.USE_YN = 'Y' WHERE 1=1
AND A.RCP_NUMBER = #{rcpNumber,jdbcType=VARCHAR}
AND A.USER_ID = #{userId,jdbcType=VARCHAR} AND A.RCP_KIND = #{rcpKind,jdbcType=VARCHAR}
ORDER BY A.RCP_NUMBER DESC, A.RCP_SEQ DESC, A.RCP_INF_SEQ DESC
LIMIT ${pageNum} , ${pageItemNum}

  	SELECT CB_RCPINFSTAT_CODE(RCP_INF_STAT) AS RCP_INF_STAT
  	  FROM GOLF_RECEIPT_INF
	 WHERE RCP_NUMBER = #{rcpNumber,jdbcType=VARCHAR}
